AstraUI.State = {
    ReducedMotion = false,
    Quality = 3,
    Mobile = false,
    Viewport = Vector2.new(1280, 720),
}

local function clamp(v,a,b) return math.max(a,math.min(b,v)) end
local function safe(fn,...)
    if type(fn) ~= "function" then return end
    local ok,err=pcall(fn,...)
    if not ok then warn("[AstraUI] Callback error:",err) end
end
local function new(class,props,parent)
    local o=Instance.new(class)
    for k,v in pairs(props or {}) do
        pcall(function() o[k]=v end)
    end
    o.Parent=parent
    return o
end
local function corner(parent,r)
    return new("UICorner",{CornerRadius=UDim.new(0,r or 12)},parent)
end
local function stroke(parent,color,transparency,thickness)
    return new("UIStroke",{Color=color,Transparency=transparency,Thickness=thickness or 1,ApplyStrokeMode=Enum.ApplyStrokeMode.Border},parent)
end
local function padding(parent,l,t,r,b)
    return new("UIPadding",{PaddingLeft=UDim.new(0,l or 0),PaddingTop=UDim.new(0,t or 0),PaddingRight=UDim.new(0,r or 0),PaddingBottom=UDim.new(0,b or 0)},parent)
end
local function list(parent,direction,gap)
    return new("UIListLayout",{FillDirection=direction or Enum.FillDirection.Vertical,Padding=UDim.new(0,gap or 0),SortOrder=Enum.SortOrder.LayoutOrder},parent)
end
local function text(parent,props)
    props=props or {}
    props.BackgroundTransparency=1
    props.Font=props.Font or Enum.Font.Gotham
    props.TextSize=props.TextSize or 14
    props.TextColor3=props.TextColor3 or Color3.new(1,1,1)
    return new("TextLabel",props,parent)
end
local function viewport()
    local camera=workspace.CurrentCamera
    return camera and camera.ViewportSize or Vector2.new(1280,720)
end

