function AstraUI:RegisterTheme(name,theme)
    assert(type(name)=="string","Theme name must be a string")
    assert(type(theme)=="table","Theme must be a table")
    local result={}
    for k,v in pairs(self.Theme) do result[k]=v end
    for k,v in pairs(theme) do result[k]=v end
    self.Themes[name]=result
    return result
end
function AstraUI:SetTheme(name)
    local theme=self.Themes[name]
    if not theme then return false end
    self.Theme=theme
    for _,window in ipairs(self.Windows) do
        if window.RefreshTheme then window:RefreshTheme() end
    end
    return true
end
function AstraUI:SetAccent(color)
    assert(typeof(color)=="Color3","Accent must be Color3")
    self.Theme.Accent=color
    for _,window in ipairs(self.Windows) do
        if window.RefreshTheme then window:RefreshTheme() end
    end
    return self
end

AstraUI.Motion={
    Presets={
        Liquid={Frequency=5.0,Damping=.78,Mass=1},
        Smooth={Frequency=3.6,Damping=.87,Mass=1},
        Snappy={Frequency=7.4,Damping=.72,Mass=.82},
        Gentle={Frequency=2.5,Damping=.92,Mass=1.2},
    },
    Preset="Liquid",
    Springs={},
    Tweens={},
}
function AstraUI.Motion:SetPreset(name)
    if not self.Presets[name] then return false end
    self.Preset=name
    return true
end
function AstraUI.Motion:Tween(object,properties,duration,easing,direction)
    if AstraUI.State.ReducedMotion then
        for k,v in pairs(properties) do pcall(function() object[k]=v end) end
        return nil
    end
    local tween=TweenService:Create(object,TweenInfo.new(duration or .22,easing or Enum.EasingStyle.Quint,direction or Enum.EasingDirection.Out),properties)
    tween:Play()
    return tween
end
function AstraUI.Motion:Spring(object,property,target,options)
    options=options or {}
    if AstraUI.State.ReducedMotion then pcall(function() object[property]=target end) return end
    local preset=self.Presets[options.Preset or self.Preset] or self.Presets.Liquid
    local current=object[property]
    self.Springs[tostring(object)..":"..property]={
        Object=object,Property=property,Value=current,Target=target,
        Velocity=options.Velocity or 0,Frequency=options.Frequency or preset.Frequency,
        Damping=options.Damping or preset.Damping,Mass=options.Mass or preset.Mass,
    }
end
function AstraUI.Motion:Cancel(object,property)
    local key=tostring(object)..":"..property
    self.Springs[key]=nil
    local tween=self.Tweens[key]
    if tween then pcall(function() tween:Cancel() end) end
    self.Tweens[key]=nil
end
function AstraUI.Motion:Scale(object,scale,duration)
    local ui=object:FindFirstChildOfClass("UIScale") or new("UIScale",{Scale=1},object)
    return self:Tween(ui,{Scale=scale},duration or .18,Enum.EasingStyle.Quint)
end
function AstraUI.Motion:Press(object)
    local scale=object:FindFirstChildOfClass("UIScale") or new("UIScale",{Scale=1},object)
    self:Tween(scale,{Scale=.975},.07,Enum.EasingStyle.Quad)
    task.delay(.07,function() if object.Parent then self:Tween(scale,{Scale=1},.17,Enum.EasingStyle.Back) end end)
end
function AstraUI.Motion:Hover(object,state)
    local scale=object:FindFirstChildOfClass("UIScale") or new("UIScale",{Scale=1},object)
    self:Tween(scale,{Scale=state and 1.012 or 1},.18,Enum.EasingStyle.Quint)
end
RunService.RenderStepped:Connect(function(dt)
    for key,s in pairs(AstraUI.Motion.Springs) do
        if not s.Object or not s.Object.Parent then
            AstraUI.Motion.Springs[key]=nil
        else
            local current=s.Value
            local target=s.Target
            local alpha=1-math.exp(-s.Frequency*8*dt)
            local ok,nextValue=pcall(function() return current:Lerp(target,alpha) end)
            if ok then
                s.Value=nextValue
                pcall(function() s.Object[s.Property]=nextValue end)
                if typeof(nextValue)=="UDim2" then
                    if math.abs(nextValue.X.Offset-target.X.Offset)<.2 and math.abs(nextValue.Y.Offset-target.Y.Offset)<.2 then
                        s.Object[s.Property]=target
                        AstraUI.Motion.Springs[key]=nil
                    end
                elseif typeof(nextValue)=="Color3" then
                    if (nextValue-target).Magnitude<.003 then
                        s.Object[s.Property]=target
                        AstraUI.Motion.Springs[key]=nil
                    end
                end
            else
                AstraUI.Motion.Springs[key]=nil
            end
        end
    end
end)

AstraUI.Responsive={
    Breakpoints={Tiny=380,Phone=520,Compact=760,Tablet=980},
}
function AstraUI.Responsive:Class(size)
    size=size or viewport()
    if size.X<=self.Breakpoints.Tiny then return "Tiny" end
    if size.X<=self.Breakpoints.Phone then return "Phone" end
    if size.X<=self.Breakpoints.Compact then return "Compact" end
    if size.X<=self.Breakpoints.Tablet then return "Tablet" end
    return "Desktop"
end
function AstraUI.Responsive:WindowSize(size)
    size=size or viewport()
    local c=self:Class(size)
    if c=="Tiny" then return UDim2.new(1,-12,1,-72) end
    if c=="Phone" then return UDim2.new(1,-20,1,-88) end
    if c=="Compact" then return UDim2.new(1,-30,1,-70) end
    if c=="Tablet" then return UDim2.fromOffset(math.min(720,size.X-60),math.min(520,size.Y-70)) end
    return UDim2.fromOffset(720,520)
end

-- Lucide-compatible registry. Roblox ImageLabels require an image asset/source.
-- Register the matching uploaded Lucide asset once, then use the Lucide name everywhere.
local lucideNames={"home","settings","search","menu","chevronDown","chevronUp","check","x","info","alertTriangle","plus","minus","play","pause","refreshCw","user","eye","eyeOff","palette","slidersHorizontal","keyboard","copy","trash2","edit3","folder","star","heart","zap","shield","globe","monitor","smartphone","moon","sun","moreHorizontal","arrowLeft","arrowRight","download","upload","lock","unlock"}
for _,name in ipairs(lucideNames) do AstraUI.Icons.Lucide[name]=nil end
function AstraUI:RegisterIcon(name,source)
    assert(type(name)=="string","Icon name must be a string")
    assert(type(source)=="string","Icon source must be a string")
    self.Icons[name]=source
    return self
end
function AstraUI:RegisterLucideIcon(name,source)
    self.Icons.Lucide[name]=source
    return self
end
function AstraUI:ResolveIcon(icon)
    if type(icon)~="string" then return nil end
    return self.Icons[icon] or self.Icons.Lucide[icon] or (icon:match("^rbxasset") and icon) or (icon:match("^https?://") and icon)
end
function AstraUI:Icon(parent,name,size,color)
    return new("ImageLabel",{BackgroundTransparency=1,Image=self:ResolveIcon(name) or "",ImageColor3=color or self.Theme.Text,Size=UDim2.fromOffset(size or 18,size or 18),ScaleType=Enum.ScaleType.Fit},parent)
end

function AstraUI:ApplyGlass(root,options)
    options=options or {}
    local t=self.Theme
    root.BackgroundColor3=options.Color or t.Surface
    root.BackgroundTransparency=options.Transparency or t.GlassTransparency
    root.BorderSizePixel=0
    root.ClipsDescendants=true
    corner(root,options.Radius or 16)
    stroke(root,options.BorderColor or t.Border,options.BorderTransparency or t.BorderTransparency,options.BorderThickness or 1)
    local highlight=new("Frame",{BackgroundColor3=Color3.new(1,1,1),BackgroundTransparency=options.HighlightTransparency or t.HighlightTransparency,BorderSizePixel=0,Position=UDim2.new(.08,0,0,1),Size=UDim2.new(.84,0,0,1),ZIndex=root.ZIndex+1},root)
    corner(highlight,1)
    new("UIGradient",{Transparency=NumberSequence.new({NumberSequenceKeypoint.new(0,1),NumberSequenceKeypoint.new(.5,.12),NumberSequenceKeypoint.new(1,1)})},highlight)
    if options.Shadow~=false then
        new("ImageLabel",{BackgroundTransparency=1,Image="rbxassetid://1316045217",ImageColor3=Color3.new(0,0,0),ImageTransparency=t.ShadowTransparency,AnchorPoint=Vector2.new(.5,.5),Position=UDim2.fromScale(.5,.5),Size=UDim2.new(1,30,1,30),ZIndex=math.max(0,root.ZIndex-1)},root)
    end
    return root
end

local Component={}
Component.__index=Component
function Component:_new(window,kind,options)
    local c=setmetatable({},self)
    c.Window=window;c.Kind=kind;c.Options=options or {};c.Destroyed=false;c.Disabled=false;c.Connections={}
    c.Id=c.Options.Id or (kind.."_"..math.random(100000,999999))
    AstraUI.Components[c.Id]=c
    table.insert(window.Components,c)
    return c
end
function Component:Connect(signal,fn)
    local connection=signal:Connect(function(...) safe(fn,...) end)
    table.insert(self.Connections,connection)
    return connection
end
function Component:SetVisible(state) if self.Root then self.Root.Visible=state==true end return self end
function Component:IsVisible() return self.Root and self.Root.Visible or false end
function Component:SetDisabled(state) self.Disabled=state==true if self.Button then self.Button.Active=not self.Disabled end return self end
function Component:IsDisabled() return self.Disabled end
function Component:Get() return self.Value end
function Component:Destroy()
    if self.Destroyed then return end
    self.Destroyed=true
    for _,c in ipairs(self.Connections) do pcall(function() c:Disconnect() end) end
    self.Connections={}
    if self.Root then self.Root:Destroy() end
    AstraUI.Components[self.Id]=nil
end

local Tab={}
Tab.__index=Tab
function Tab:_new(window,options)
    local t=setmetatable({},Tab)
    t.Window=window;t.Name=options.Name or "Tab";t.Icon=options.Icon;t.Components={};t.Active=false
    t.Button=new("TextButton",{Text="",BackgroundColor3=AstraUI.Theme.Surface2,BackgroundTransparency=.72,BorderSizePixel=0,Size=UDim2.new(1,0,0,42),AutoButtonColor=false},window.Nav)
    corner(t.Button,11)
    t.IconImage=AstraUI:Icon(t.Button,t.Icon,17,AstraUI.Theme.Muted);t.IconImage.Position=UDim2.fromOffset(12,12)
    t.Label=text(t.Button,{Text=t.Name,TextColor3=AstraUI.Theme.Muted,TextSize=12,Font=Enum.Font.GothamMedium,Position=UDim2.fromOffset(38,0),Size=UDim2.new(1,-42,1,0)})
    t.Page=new("ScrollingFrame",{BackgroundTransparency=1,BorderSizePixel=0,Size=UDim2.fromScale(1,1),Visible=false,AutomaticCanvasSize=Enum.AutomaticSize.Y,ScrollBarThickness=3},window.Content)
    padding(t.Page,8,6,8,12);list(t.Page,Enum.FillDirection.Vertical,8)
    t.Button.MouseButton1Click:Connect(function() window:SelectTab(t.Name) end)
    t.Button.MouseEnter:Connect(function() if not t.Active then AstraUI.Motion:Hover(t.Button,true) end end)
    t.Button.MouseLeave:Connect(function() if not t.Active then AstraUI.Motion:Hover(t.Button,false) end end)
    return t
end
function Tab:SetActive(state)
    self.Active=state==true;self.Page.Visible=self.Active
    AstraUI.Motion:Tween(self.Button,{BackgroundTransparency=self.Active and .28 or .72},.2)
    AstraUI.Motion:Tween(self.Label,{TextColor3=self.Active and AstraUI.Theme.Text or AstraUI.Theme.Muted},.18)
    if self.IconImage then AstraUI.Motion:Tween(self.IconImage,{ImageColor3=self.Active and AstraUI.Theme.Accent or AstraUI.Theme.Muted},.18) end
end
function Tab:_register(c) table.insert(self.Components,c) return c end
function Tab:CreateSection(name) local c=Component:_new(self.Window,"Section",{Name=name});setmetatable(c,{__index=Component});c.Root=new("Frame",{BackgroundTransparency=1,Size=UDim2.new(1,0,0,28)},self.Page);c.Label=text(c.Root,{Text=name or "Section",TextColor3=AstraUI.Theme.Text,TextSize=12,Font=Enum.Font.GothamBold,Size=UDim2.fromScale(1,1)});return self:_register(c) end

local function row(tab,kind,options,height)
    local c=Component:_new(tab.Window,kind,options);setmetatable(c,{__index=Component});c.Tab=tab
    c.Root=new("Frame",{BackgroundColor3=AstraUI.Theme.Surface2,BackgroundTransparency=options.Transparency or .35,BorderSizePixel=0,Size=UDim2.new(1,0,0,height or 54)},tab.Page)
    AstraUI:ApplyGlass(c.Root,{Radius=options.Radius or 13,Transparency=options.Transparency or .35,Shadow=false})
    return c
end

