    options=options or {};local c=row(self,"Button",options,options.Height or 54);c.Title=text(c.Root,{Text=options.Name or "Button",TextColor3=AstraUI.Theme.Text,TextSize=13,Font=Enum.Font.GothamMedium,Position=UDim2.fromOffset(14,6),Size=UDim2.new(1,-55,0,21)});c.Description=text(c.Root,{Text=options.Description or "",TextColor3=AstraUI.Theme.Muted,TextSize=10,Position=UDim2.fromOffset(14,28),Size=UDim2.new(1,-55,0,17)});c.Button=new("TextButton",{Text="",BackgroundTransparency=1,Size=UDim2.fromScale(1,1),AutoButtonColor=false},c.Root);c.Icon=AstraUI:Icon(c.Root,options.Icon,18,AstraUI.Theme.Muted);c.Icon.Position=UDim2.new(1,-34,.5,-9);c.Callback=options.Callback;c.Button.MouseButton1Click:Connect(function() AstraUI.Motion:Press(c.Root);safe(c.Callback) end);return c
