    options=options or {};local c=row(self,"Toggle",options,options.Height or 58);c.Value=options.CurrentValue==true;c.Callback=options.Callback;c.Title=text(c.Root,{Text=options.Name or "Toggle",TextColor3=AstraUI.Theme.Text,TextSize=13,Font=Enum.Font.GothamMedium,Position=UDim2.fromOffset(14,7),Size=UDim2.new(1,-90,0,20)});c.Description=text(c.Root,{Text=options.Description or "",TextColor3=AstraUI.Theme.Muted,TextSize=10,Position=UDim2.fromOffset(14,29),Size=UDim2.new(1,-90,0,17)});c.Track=new("Frame",{BackgroundColor3=c.Value and AstraUI.Theme.Accent or AstraUI.Theme.Elevated,BorderSizePixel=0,AnchorPoint=Vector2.new(1,.5),Position=UDim2.new(1,-14,.5,0),Size=UDim2.fromOffset(42,22)},c.Root);corner(c.Track,11);c.Knob=new("Frame",{BackgroundColor3=Color3.new(1,1,1),BorderSizePixel=0,AnchorPoint=Vector2.new(.5,.5),Position=UDim2.new(c.Value and .72 or .28,0,.5,0),Size=UDim2.fromOffset(17,17)},c.Track);corner(c.Knob,9);c.Button=new("TextButton",{Text="",BackgroundTransparency=1,Size=UDim2.fromScale(1,1),AutoButtonColor=false},c.Root);c.Button.MouseButton1Click:Connect(function() c:Set(not c.Value) end);return c
