local Window={}
Window.__index=Window
function Window:_build()
    self.Gui=new("ScreenGui",{Name="AstraUI_"..self.Id,ResetOnSpawn=false,IgnoreGuiInset=true,ZIndexBehavior=Enum.ZIndexBehavior.Sibling,DisplayOrder=self.Options.DisplayOrder or 50},PlayerGui)
    self.Root=new("Frame",{Name="Window",AnchorPoint=Vector2.new(.5,.5),Position=UDim2.fromScale(.5,.5),Size=self.Options.Size or AstraUI.Responsive:WindowSize(),BackgroundColor3=AstraUI.Theme.Surface,BackgroundTransparency=AstraUI.Theme.GlassTransparency,BorderSizePixel=0,Active=true,ClipsDescendants=true},self.Gui)
    AstraUI:ApplyGlass(self.Root,{Radius=self.Options.Radius or 20,Transparency=AstraUI.Theme.GlassTransparency})
    self.Topbar=new("Frame",{BackgroundTransparency=1,Size=UDim2.new(1,0,0,60)},self.Root)
    padding(self.Topbar,18,9,14,8)
    self.Title=text(self.Topbar,{Text=self.Options.Title or "AstraUI",TextColor3=AstraUI.Theme.Text,TextSize=17,Font=Enum.Font.GothamBold,Position=UDim2.fromOffset(0,0),Size=UDim2.new(1,-80,0,25)})
    self.Subtitle=text(self.Topbar,{Text=self.Options.Subtitle or "Liquid Glass",TextColor3=AstraUI.Theme.Muted,TextSize=11,Position=UDim2.fromOffset(0,25),Size=UDim2.new(1,-80,0,18)})
    self.Close=new("TextButton",{Text="×",TextColor3=AstraUI.Theme.Muted,TextSize=24,Font=Enum.Font.Gotham,BackgroundTransparency=1,AnchorPoint=Vector2.new(1,0),Position=UDim2.new(1,0,0,0),Size=UDim2.fromOffset(34,34),AutoButtonColor=false},self.Topbar)
    self.Close.MouseButton1Click:Connect(function() self:Close() end)
    self.Body=new("Frame",{BackgroundTransparency=1,Position=UDim2.fromOffset(12,62),Size=UDim2.new(1,-24,1,-74)},self.Root)
    self.Nav=new("ScrollingFrame",{BackgroundTransparency=1,BorderSizePixel=0,Size=UDim2.new(0,172,1,0),AutomaticCanvasSize=Enum.AutomaticSize.Y,ScrollBarThickness=0},self.Body)
    padding(self.Nav,4,4,4,4);list(self.Nav,Enum.FillDirection.Vertical,6)
    self.Content=new("Frame",{BackgroundTransparency=1,Position=UDim2.fromOffset(184,0),Size=UDim2.new(1,-184,1,0)},self.Body)
end
function Window:CreateTab(options) local tab=Tab:_new(self,options or {});table.insert(self.Tabs,tab);self.TabMap[tab.Name]=tab;if #self.Tabs==1 then self:SelectTab(tab.Name) end;return tab end
function Window:GetTab(name) return self.TabMap[name] end
function Window:SelectTab(name) local tab=self.TabMap[name];if not tab then return false end;for _,other in ipairs(self.Tabs) do other:SetActive(other==tab) end;self.ActiveTab=tab;return true end
function Window:Open() self.Visible=true;self.Root.Visible=true;AstraUI.Motion:Spring(self.Root,"Size",self.Options.Size or AstraUI.Responsive:WindowSize(),{Preset="Liquid"});return self end
function Window:Close() self.Visible=false;AstraUI.Motion:Scale(self.Root,.97,.15);task.delay(.15,function() if self.Root then self.Root.Visible=false end end);return self end
function Window:Toggle() if self.Visible then return self:Close() else return self:Open() end end
function Window:ToggleMinimize() self.Minimized=not self.Minimized;self.Body.Visible=not self.Minimized;return self end
function Window:SetTitle(title,subtitle) self.Title.Text=title or self.Title.Text;if subtitle then self.Subtitle.Text=subtitle end;return self end
function Window:SetSize(size) self.Options.Size=size;AstraUI.Motion:Spring(self.Root,"Size",size,{Preset="Liquid"});return self end
function Window:SetPosition(position) AstraUI.Motion:Spring(self.Root,"Position",position,{Preset="Liquid"});return self end
function Window:SetVisibility(state) if state then return self:Open() else return self:Close() end end
function Window:Search(query) self.SearchText=string.lower(query or "");for _,tab in ipairs(self.Tabs) do for _,component in ipairs(tab.Components) do local hay=string.lower(tostring(component.Options.Name or component.Kind));component:SetVisible(self.SearchText=="" or string.find(hay,self.SearchText,1,true)~=nil) end end;return self end
function Window:RefreshTheme()
    local t=AstraUI.Theme
    self.Root.BackgroundColor3=t.Surface;self.Root.BackgroundTransparency=t.GlassTransparency
    self.Title.TextColor3=t.Text;self.Subtitle.TextColor3=t.Muted
    for _,tab in ipairs(self.Tabs) do tab.Label.TextColor3=tab.Active and t.Text or t.Muted;tab.IconImage.ImageColor3=tab.Active and t.Accent or t.Muted end
    return self
end
function Window:ApplyResponsive()
    local size=viewport();AstraUI.State.Viewport=size;AstraUI.State.Mobile=UserInputService.TouchEnabled and size.X<850
    local class=AstraUI.Responsive:Class(size)
    if self.Options.Responsive~=false then AstraUI.Motion:Spring(self.Root,"Size",AstraUI.Responsive:WindowSize(size),{Preset="Smooth"}) end
    if class=="Desktop" or class=="Tablet" then
        self.Nav.Size=UDim2.new(0,172,1,0);self.Content.Position=UDim2.fromOffset(184,0);self.Content.Size=UDim2.new(1,-184,1,0)
    else
        self.Nav.Size=UDim2.new(0,60,1,0);self.Content.Position=UDim2.fromOffset(70,0);self.Content.Size=UDim2.new(1,-70,1,0)
    end
