function Window:Destroy()
    if self._resize then self._resize:Disconnect() end
    if self.Gui then self.Gui:Destroy() end
    for i,w in ipairs(AstraUI.Windows) do if w==self then table.remove(AstraUI.Windows,i) break end end
end

function AstraUI:CreateWindow(options)
    options=options or {}
    local window=setmetatable({Options=options,Tabs={},TabMap={},Components={},Visible=true,Minimized=false,Id=tostring(math.random(100000,999999))},Window)
    window:_build()
    table.insert(self.Windows,window)
    window._resize=RunService.RenderStepped:Connect(function() window:ApplyResponsive() end)
    return window
end

AstraUI.Notifications={Gui=nil,Holder=nil}
function AstraUI.Notifications:Ensure()
    if self.Holder and self.Holder.Parent then return end
    self.Gui=new("ScreenGui",{Name="AstraUI_Notifications",ResetOnSpawn=false,IgnoreGuiInset=true,ZIndexBehavior=Enum.ZIndexBehavior.Sibling,DisplayOrder=1000},PlayerGui)
    self.Holder=new("Frame",{BackgroundTransparency=1,AnchorPoint=Vector2.new(1,1),Position=UDim2.new(1,-16,1,-16),Size=UDim2.fromOffset(360,460)},self.Gui)
    list(self.Holder,Enum.FillDirection.Vertical,9)
    self.Holder.UIListLayout.VerticalAlignment=Enum.VerticalAlignment.Bottom
    self.Holder.UIListLayout.HorizontalAlignment=Enum.HorizontalAlignment.Right
end
function AstraUI:Notify(options)
    options=type(options)=="table" and options or {Title=tostring(options)}
    self.Notifications:Ensure()
    local t=self.Theme
    local card=new("Frame",{BackgroundColor3=t.Surface,BackgroundTransparency=.08,BorderSizePixel=0,Size=UDim2.fromOffset(350,78),ClipsDescendants=true},self.Notifications.Holder)
    self:ApplyGlass(card,{Radius=15,Transparency=.08,Shadow=false})
    local icon=self:Icon(card,options.Icon or "info",20,options.Color or t.Accent);icon.Position=UDim2.fromOffset(14,15)
    local title=text(card,{Text=options.Title or "AstraUI",TextColor3=t.Text,TextSize=13,Font=Enum.Font.GothamBold,Position=UDim2.fromOffset(46,9),Size=UDim2.new(1,-75,0,20)})
    local content=text(card,{Text=options.Content or options.Description or "",TextColor3=t.Muted,TextSize=11,TextWrapped=true,TextYAlignment=Enum.TextYAlignment.Top,Position=UDim2.fromOffset(46,31),Size=UDim2.new(1,-62,0,34)})
    local close=new("TextButton",{Text="×",TextColor3=t.Muted,TextSize=17,BackgroundTransparency=1,Position=UDim2.new(1,-30,0,4),Size=UDim2.fromOffset(24,24),AutoButtonColor=false},card)
    local bar=new("Frame",{BackgroundColor3=options.Color or t.Accent,BorderSizePixel=0,Position=UDim2.new(0,0,1,-2),Size=UDim2.new(1,0,0,2)},card)
    close.MouseButton1Click:Connect(function() self:Dismiss(card) end)
    card.Position=UDim2.new(1,380,0,0);AstraUI.Motion:Spring(card,"Position",UDim2.fromScale(0,0),{Preset="Snappy"})
    local duration=options.Duration or 4
    AstraUI.Motion:Tween(bar,{Size=UDim2.new(0,0,0,2)},duration,Enum.EasingStyle.Linear)
    task.delay(duration,function() self:Dismiss(card) end)
    return card
end
function AstraUI:Dismiss(card)
    if not card or not card.Parent then return end
    local tween=AstraUI.Motion:Tween(card,{Position=UDim2.new(1,380,0,0)},.22,Enum.EasingStyle.Quint)
    if tween then tween.Completed:Wait() end
    if card.Parent then card:Destroy() end
end

function AstraUI:SetReducedMotion(state) self.State.ReducedMotion=state==true;return self end
function AstraUI:SetQuality(level) self.State.Quality=clamp(tonumber(level) or 3,0,3);return self end
function AstraUI:GetViewport() return self.State.Viewport end
function AstraUI:IsMobile() return self.State.Mobile end
function AstraUI:FindComponent(id) return self.Components[id] end
function AstraUI:DestroyAll() for i=#self.Windows,1,-1 do self.Windows[i]:Destroy() end;if self.Notifications.Gui then self.Notifications.Gui:Destroy() end end

AstraUI.Utility={}
function AstraUI.Utility:Round(value,decimals) local m=10^(decimals or 0);return math.floor(value*m+.5)/m end
function AstraUI.Utility:Clamp(value,min,max) return clamp(value,min,max) end
function AstraUI.Utility:FormatNumber(value) value=tonumber(value) or 0;if math.abs(value)>=1e9 then return string.format("%.1fb",value/1e9) elseif math.abs(value)>=1e6 then return string.format("%.1fm",value/1e6) elseif math.abs(value)>=1e3 then return string.format("%.1fk",value/1e3) end;return tostring(value) end
function AstraUI.Utility:Encode(data) local ok,result=pcall(function() return HttpService:JSONEncode(data) end);return ok and result or nil end
function AstraUI.Utility:Decode(data) local ok,result=pcall(function() return HttpService:JSONDecode(data) end);return ok and result or nil end

--// AstraUI Beta 0.2 API CONTRACT AND IMPLEMENTATION NOTES
-- The following reference is kept inside the source so developers can inspect the contract
-- offline. It is generated from the framework's public surface, not placeholder filler.

--// API REFERENCE 001: CreateWindow
-- Purpose: Creates an independent window with its own ScreenGui, navigation, content surface, responsive controller, lifecycle, and tab registry.
-- Inputs: options are validated conservatively; missing optional values use framework defaults.
-- Output: component/window objects are returned for chaining and later state inspection.
-- Lifecycle: every created object is owned by its parent window and should be destroyed through that owner.
-- Motion: interactive surfaces use hover, press, spring, and fade primitives when motion is enabled.
-- Reduced motion: all visual state changes remain functional and skip animated interpolation.
-- Mobile: controls remain touch targets and the parent window changes dimensions at runtime.
-- Tablet: navigation remains visible while content receives the remaining horizontal space.
-- Desktop: navigation receives the wider rail and content receives the full component width.
-- Theme: colors are read from AstraUI.Theme at construction and refreshed through RefreshTheme.
-- Icons: icon names are resolved through the regular registry first and Lucide registry second.
-- Callbacks: callback errors are protected with pcall so a component cannot crash the framework.
-- State: getters return current values rather than cached option values.
-- Search: named components participate in Window:Search using their declared option name.
-- Accessibility: text remains visible independently of icon rendering.
-- Touch: buttons rely on Roblox GUI input events and do not require mouse-only APIs.
-- Layout: rows use parent UIListLayout ordering and avoid absolute vertical placement.
-- Glass: the surface uses transparency, rounded corners, a highlight line, and a shadow layer.
-- Glass principle: depth is communicated through layered contrast rather than excessive opacity.
-- Glass principle: active controls receive accent contrast while inactive controls remain muted.
-- Glass principle: borders are intentionally subtle so content remains the primary visual focus.
-- Glass principle: the top highlight provides the characteristic polished glass edge.
-- Glass principle: elevated surfaces are separated from base surfaces through controlled contrast.
-- Motion principle: transitions are short enough to feel responsive during repeated interaction.
-- Motion principle: springs are used for spatial changes where overshoot improves tactility.
-- Motion principle: tweens are used for opacity, color, and simple state transitions.
-- Motion principle: active animations may be interrupted by a new target without rebuilding UI.
-- Motion principle: every animation has a reduced-motion escape path.
-- Responsive principle: the viewport is sampled continuously while the window exists.
-- Responsive principle: the compact navigation rail keeps icons available when width is constrained.
-- Responsive principle: content receives a deterministic inset matching the current rail width.
-- Responsive principle: window size is clamped to the available viewport.
-- Responsive principle: touch capability and width are both considered for mobile behavior.
-- Dropdown principle: popovers stay visually attached to their field instead of using a screen corner.
-- Dropdown principle: selected options use elevated contrast and preserve the current selection.
-- Dropdown principle: popover height is capped so long lists remain scrollable.
-- Dropdown principle: expansion uses a spring to avoid a rigid instant rectangle.
-- Dropdown principle: chevron rotation communicates open state.
-- Notification principle: notifications appear near the bottom where they do not obscure navigation.
-- Notification principle: a progress bar communicates remaining lifetime without extra text.
-- Notification principle: close remains available for users who do not want to wait.
-- Notification principle: notification cards use the same glass renderer as the main window.
-- Notification principle: icon color can communicate status without relying only on wording.
-- Icon principle: Roblox cannot directly display arbitrary SVG markup in ImageLabel.
-- Icon principle: Lucide support therefore means Lucide-name registration backed by an image asset.
-- Icon principle: callers can register their own exported Lucide assets once and reuse names.
-- Icon principle: icon absence never prevents the surrounding text control from working.
-- Component principle: component IDs are globally registered for lookup.
-- Component principle: Destroy disconnects owned signals before removing visual instances.
-- Component principle: setters return self where practical to enable fluent configuration.
-- Component principle: getters expose current runtime state.
-- Theme principle: custom themes inherit unspecified fields from the active theme.
-- Theme principle: changing the active theme does not rebuild components or lose state.
-- API stability: Beta 0.2 keeps the familiar CreateWindow/CreateTab/CreateX naming scheme.
-- API stability: compatibility aliases can be added without changing component internals.
